import { readFileSync } from 'node:fs'
const shell = readFileSync('.next/server/app/index.html', 'utf8')
const responses = await Promise.all([fetch('http://127.0.0.1:3217/'), fetch('http://127.0.0.1:3217/')])
const html = await Promise.all(responses.map(response => response.text()))
for (const [name, text] of [['shell', shell], ['request1', html[0]], ['request2', html[1]]]) {
  console.log(name, 'nav:', text.includes('<nav><a href="/">Operations</a></nav>'), 'page:', text.includes('Deployment health'), 'fallback:', text.includes('Loading request details'), 'metadata:', text.match(/Request [\w-]+ generated at [^<\\]+/)?.[0] ?? 'none')
}
console.log('statuses:', responses.map(r => r.status).join(', '))
